local t=require('kui.test')
t.describe('counter',function()
  t.before_each(function() t.start() end)
  t.it('routes a labelled press',function()
    t.expect(t.model().count):to_be(0)
    t.press('Increment')
    t.expect(t.model().count):to_be(1)
    t.expect_tree('counter')
    t.expect_quads('counter')
    t.expect_table('state',t.model())
  end)
  t.it('has fresh state and virtual timers',function()
    t.expect(t.model().count):to_be(0)
    t.dispatch {kind='later'}
    t.advance(499)
    t.expect(t.model().count):to_be(0)
    t.advance(1)
    t.expect(t.model().count):to_be(1)
  end)
  t.it('mocks native HTTP',function()
    t.mock_http {url='https://example.test/count',response={status=200,body='42'},delay=50}
    t.dispatch {kind='fetch'}
    t.wait_for(function() return t.model().reply~=nil end)
    t.expect(t.model().reply):to_be('42')
    t.expect(#t.calls('http')):to_be(1)
  end)
  t.it('uses managed temporary files',function()
    local path=kui.fs.temp_file {suffix='.txt'}
    kui.fs.write(path,'hello')
    t.expect(kui.fs.read(path)):to_be('hello')
  end)
end)
